<script setup>
import { computed, ref, watch } from 'vue';
import { Link, router, useForm, usePage } from '@inertiajs/vue3';
import AssessmentLayout from './AssessmentLayout.vue';
import { confirmAction } from './confirmAction.js';
const props = defineProps({rubric:Object,criteria:Array,levels:Array,matrix:Object}); const page = usePage();
const form = useForm({title:props.rubric.title,description:props.rubric.description || '',descriptions:[]});
const cells = ref({}); const criterionDrafts = ref({}); const levelDrafts = ref({});
const hydrate = () => {cells.value=Object.fromEntries(props.criteria.map(c=>[c.id,Object.fromEntries(props.levels.map(l=>[l.id,props.matrix?.[c.id]?.[l.id] || '']))]));criterionDrafts.value=Object.fromEntries(props.criteria.map(c=>[c.id,{name:c.name,weight:c.weight,order:c.order}]));levelDrafts.value=Object.fromEntries(props.levels.map(l=>[l.id,{level:l.level,label:l.label,score_value:l.score_value}]));};
hydrate();watch(()=>[props.criteria,props.levels,props.matrix],hydrate);
const totalWeight = computed(()=>props.criteria.reduce((sum,c)=>sum+Number(c.weight || 0),0));
const criterionForm=useForm({name:'',weight:0,order:null});const levelForm=useForm({level:props.levels.length+1,label:'',score_value:0});
const save = () => {form.descriptions=props.criteria.flatMap(c=>props.levels.map(l=>({criteria_id:c.id,level_id:l.id,description:cells.value[c.id]?.[l.id] || ''})));form.put(route('admin.rubrics.update',props.rubric.id));};
const addCriterion = () => criterionForm.post(route('admin.rubrics.criteria.store',props.rubric.id),{preserveScroll:true,onSuccess:()=>criterionForm.reset()});
const addLevel = () => levelForm.post(route('admin.rubrics.levels.store',props.rubric.id),{preserveScroll:true,onSuccess:()=>{levelForm.label='';levelForm.level=props.levels.length+1;levelForm.score_value=0;}});
const saveCriterion = c => router.patch(route('admin.rubrics.criteria.update',{rubric:props.rubric.id,criterion:c.id}),criterionDrafts.value[c.id],{preserveScroll:true});
const saveLevel = l => router.patch(route('admin.rubrics.levels.update',{rubric:props.rubric.id,level:l.id}),levelDrafts.value[l.id],{preserveScroll:true});
const deleteCriterion = async c => {if(await confirmAction(`Hapus kriteria ${c.name}?`)) router.delete(route('admin.rubrics.criteria.destroy',{rubric:props.rubric.id,criterion:c.id}),{preserveScroll:true});};
const deleteLevel = async l => {if(await confirmAction(`Hapus level ${l.label}?`)) router.delete(route('admin.rubrics.levels.destroy',{rubric:props.rubric.id,level:l.id}),{preserveScroll:true});};
</script>
<template><AssessmentLayout title="Rubric editor" :subtitle="rubric.title"><template #action><Link class="secondary" :href="route('redesign.rubrics.show',rubric.id)">Lihat preview skor</Link></template><section class="panel summary"><div><h2>{{ rubric.title }}</h2><p class="muted">{{ rubric.description || 'Belum ada deskripsi.' }}</p><strong>Total bobot: {{ totalWeight }} · {{ criteria.length }} kriteria · {{ levels.length }} level</strong></div></section><p v-if="page.props.flash?.message" class="success">{{ page.props.flash.message }}</p><p v-if="Object.keys(page.props.errors || {}).length" class="error">{{ Object.values(page.props.errors).join(' · ') }}</p><form class="panel matrix-panel" @submit.prevent="save"><h2>Rubric matrix</h2><div class="fields"><label class="wide">Nama rubrik<input v-model="form.title" required maxlength="255" /></label><label class="wide">Deskripsi<textarea v-model="form.description" rows="2" /></label></div><div class="table-wrap"><table class="matrix"><thead><tr><th>Kriteria / bobot</th><th v-for="level in levels" :key="level.id">{{ level.label }} · {{ level.score_value }}</th></tr></thead><tbody><tr v-for="criterion in criteria" :key="criterion.id"><th>{{ criterion.name }} · {{ criterion.weight }}%</th><td v-for="level in levels" :key="level.id"><textarea v-model="cells[criterion.id][level.id]" :aria-label="`${criterion.name} pada ${level.label}`" rows="3" placeholder="Deskripsi penilaian" /></td></tr><tr v-if="!criteria.length"><td :colspan="levels.length+1" class="muted">Tambahkan kriteria untuk mengisi matriks.</td></tr></tbody></table></div><div class="actions"><button class="primary" :disabled="form.processing">Simpan rubrik</button><Link class="secondary" :href="route('redesign.rubrics')">Kembali</Link></div></form><div class="management"><section class="panel"><h2>Kriteria &amp; bobot</h2><div v-for="criterion in criteria" :key="criterion.id" class="manage-row"><input v-model="criterionDrafts[criterion.id].name" :aria-label="`Nama ${criterion.name}`" /><input v-model.number="criterionDrafts[criterion.id].weight" type="number" min="0" step="0.01" aria-label="Bobot" /><input v-model.number="criterionDrafts[criterion.id].order" type="number" min="0" aria-label="Urutan" /><button class="action" type="button" @click="saveCriterion(criterion)">Simpan</button><button class="remove" type="button" @click="deleteCriterion(criterion)">Hapus</button></div><form class="manage-row" @submit.prevent="addCriterion"><input v-model="criterionForm.name" placeholder="Nama kriteria" required /><input v-model.number="criterionForm.weight" type="number" min="0" step="0.01" placeholder="Bobot" required /><span></span><button class="primary">+ Kriteria</button></form></section><section class="panel"><h2>Level penilaian</h2><div v-for="level in levels" :key="level.id" class="manage-row"><input v-model="levelDrafts[level.id].label" :aria-label="`Nama level ${level.label}`" /><input v-model.number="levelDrafts[level.id].score_value" type="number" min="0" step="0.01" aria-label="Nilai level" /><input v-model.number="levelDrafts[level.id].level" type="number" min="1" aria-label="Urutan level" /><button class="action" type="button" @click="saveLevel(level)">Simpan</button><button class="remove" type="button" @click="deleteLevel(level)">Hapus</button></div><form class="manage-row" @submit.prevent="addLevel"><input v-model="levelForm.label" placeholder="Nama level" required /><input v-model.number="levelForm.score_value" type="number" min="0" step="0.01" placeholder="Nilai" required /><input v-model.number="levelForm.level" type="number" min="1" required /><button class="primary">+ Level</button></form></section></div></AssessmentLayout></template>
<style scoped>.summary{margin-bottom:20px}.summary strong{font-size:13px;color:#00857c}.matrix-panel .fields{margin:20px 0}.matrix{min-width:900px}.matrix th{min-width:150px}.matrix td{min-width:160px}.matrix textarea{min-height:80px}.management{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:20px}.manage-row{display:grid;grid-template-columns:minmax(110px,1fr) 75px 70px auto auto;gap:6px;margin:10px 0;align-items:center}.manage-row :is(input,button){font-size:11px}.manage-row .remove{border:0;background:none;color:#b74336;cursor:pointer}@media(max-width:1100px){.management{grid-template-columns:1fr}}@media(max-width:650px){.manage-row{grid-template-columns:1fr 1fr}.manage-row input:first-child{grid-column:1/-1}}</style>
